import 'package:flutter/material.dart'; import 'package:intl/intl.dart'; import '../data/database.dart'; import '../models/models.dart';
class TasksScreen extends StatefulWidget{const TasksScreen({super.key});@override State<TasksScreen> createState()=>_S();} class _S extends State<TasksScreen>{final db=AppDb.instance;List<Task> items=[];int streak=0;String get date=>DateFormat('yyyy-MM-dd').format(DateTime.now());@override void initState(){super.initState();load();}Future<void>load()async{await db.ensureTasks(date);final x=await db.tasks(date),s=await db.streak(date);if(mounted)setState(() { items=x; streak=s; });}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Daily Tasks'),actions:[Padding(padding:const EdgeInsets.only(right:16),child:Center(child:Text('🔥 $streak')))]),body:ListView(padding:const EdgeInsets.all(16),children:[...['Editing','Outreach','Study','Course Building'].map((cat)=>_section(cat)),const SizedBox(height:12),FilledButton.icon(onPressed:()async{final title=TextEditingController();String cat='Editing';await showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Add task'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Task')),DropdownButtonFormField(value:cat,items:['Editing','Outreach','Study','Course Building'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>cat=v!,decoration:const InputDecoration(labelText:'Category'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{if(title.text.trim().isNotEmpty){await (await db.db).insert('tasks',{'title':title.text.trim(),'category':cat,'date':date,'completed':0});}if(c.mounted)Navigator.pop(c);load();},child:const Text('Add'))]));},icon:const Icon(Icons.add),label:const Text('Add task'))]));Widget _section(String cat){final xs=items.where((x)=>x.category==cat).toList();return Card(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.all(16),child:Text(cat,style:const TextStyle(fontWeight:FontWeight.bold))),...xs.map((t)=>CheckboxListTile(value:t.completed,onChanged:(_)async{await db.toggleTask(t);load();},title:Text(t.title,style:TextStyle(decoration:t.completed?TextDecoration.lineThrough:null)),contentPadding:const EdgeInsets.symmetric(horizontal:12))) ]));}}
